// ── Maintenance Mode ─────────────────────────────────────────────────────────
// Toggle by setting maintenanceMode: true/false on the Firestore doc meta/maintenance.
// Fires in real-time — users already on the page are signed out and locked out immediately.
onSnapshot(doc(db, 'meta', 'maintenance'), (snap) => {
    const on = snap.exists() && snap.data().maintenanceMode === true;
    window._maintenanceModeOn = on;
    // Keep admin toggle button in sync if it's rendered
    const btn = document.getElementById('admin-maintenance-btn');
    if (btn) {
        btn.textContent = on ? '🟢 Turn Off Maintenance' : '🔴 Turn On Maintenance';
        btn.style.background = on ? '#10b981' : '#ef4444';
    }
    let overlay = document.getElementById('maintenance-overlay');
    if (on && !window.isAdmin) {
        if (auth.currentUser) signOut(auth).catch(() => {});
        if (!overlay) {
            overlay = document.createElement('div');
            overlay.id = 'maintenance-overlay';
            overlay.style.cssText = 'position:fixed;inset:0;z-index:99999;background:#0d0f14;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;font-family:inherit;';
            overlay.innerHTML = `
                <div style="font-size:48px;">🐝</div>
                <div style="font-size:24px;font-weight:800;color:#ffc107;letter-spacing:1px;">Down for Maintenance</div>
                <div style="font-size:15px;color:#aaa;max-width:340px;text-align:center;line-height:1.6;">WeeBee is getting some updates. We'll be back shortly — hang tight!</div>
                <button id="maintenance-signin-btn" style="margin-top:8px;padding:10px 24px;border-radius:8px;border:1px solid #333;background:transparent;color:#555;font-size:13px;cursor:pointer;">Admin Sign In</button>
            `;
            document.body.appendChild(overlay);
            document.getElementById('maintenance-signin-btn').addEventListener('click', () => {
                signInWithPopup(auth, googleProvider).catch(() => {});
            });
        }
    } else if (overlay) {
        overlay.remove();
    }
});

window._maintenance = async function(on) {
    await setDoc(doc(db, 'meta', 'maintenance'), { maintenanceMode: on });
    console.log('Maintenance mode:', on ? 'ON' : 'OFF');
};

window._adminToggleMaintenance = async function() {
    if (!window.isAdmin) return;
    const turningOn = !window._maintenanceModeOn;
    const msg = turningOn
        ? '⚠️ Turn ON maintenance mode?\n\nAll non-admin users will be signed out and locked out immediately.'
        : 'Turn OFF maintenance mode? The site will become publicly accessible again.';
    if (!confirm(msg)) return;
    const btn = document.getElementById('admin-maintenance-btn');
    if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }
    try {
        await window._maintenance(turningOn);
    } catch(e) {
        alert('Failed to toggle maintenance mode: ' + e.message);
        if (btn) btn.disabled = false;
    }
};

// --- RANK SYSTEM ---
window.myReviewCount = 0;
window.userRankCache = {};
window.userPinnedBadgesCache = {};

window.getRankInfo = function(count) {
    if (count >= 100) return { name: 'Diamond',  icon: 'diamond',           color: '#00BCD4', next: null, min: 100 };
    if (count >= 40)  return { name: 'Gold',     icon: 'workspace_premium', color: '#FFC107', next: 100,  min: 40  };
    if (count >= 15)  return { name: 'Silver',   icon: 'workspace_premium', color: '#9E9E9E', next: 40,   min: 15  };
    if (count >= 5)   return { name: 'Bronze',   icon: 'workspace_premium', color: '#CD7F32', next: 15,   min: 5   };
    return             { name: 'Newcomer', icon: 'grade',             color: '#BDBDBD', next: 5,    min: 0   };
};

window.getRankBadgeHTML = function(count, size = 18) {
    const r = window.getRankInfo(count);
    const tip = r.next ? `${r.name} · ${count}/${r.next} reviews` : `${r.name} · ${count} reviews`;
    return `<span class="material-symbols-outlined" title="${tip}" style="font-size:${size}px; color:${r.color}; cursor:default; vertical-align:middle; line-height:1;">${r.icon}</span>`;
};

window.prefetchRankCache = async function(uids) {
    const unique = [...new Set(uids)].filter(uid => uid && window.userRankCache[uid] === undefined);
    if (!unique.length) return;
    await Promise.all(unique.map(async uid => {
        try {
            const d = await getDoc(doc(db, "profiles", uid));
            window.userRankCache[uid] = d.exists() ? (d.data().reviewCount || 0) : 0;
            window.userPinnedBadgesCache[uid] = d.exists() ? (d.data().pinnedBadges || []) : [];
        } catch(e) { window.userRankCache[uid] = 0; window.userPinnedBadgesCache[uid] = []; }
    }));
};

window.getPinnedBadgesHTML = function(uid, size = 17) {
    const pins = window.userPinnedBadgesCache[uid] || [];
    if (!pins.length) return '';
    return pins.map(id => {
        const ach = ACHIEVEMENTS.find(a => a.id === id);
        if (!ach) return '';
        return `<span class="material-symbols-outlined" title="${ach.name}: ${ach.desc}" style="font-size:${size}px;color:${ach.color};cursor:default;vertical-align:middle;line-height:1;">${ach.icon}</span>`;
    }).join('')
};

window.updateTopbarRank = async function() {
    if (!auth.currentUser) return;
    try {
        const pd = await getDoc(doc(db, "profiles", auth.currentUser.uid));
        const count = pd.exists() ? (pd.data().reviewCount || 0) : 0;
        window.myReviewCount = count;
        window.userRankCache[auth.currentUser.uid] = count;
        window.userPinnedBadgesCache[auth.currentUser.uid] = pd.exists() ? (pd.data().pinnedBadges || []) : [];
        const el = document.getElementById('topbar-rank-badge');
        if (el) el.innerHTML = window.getRankBadgeHTML(count, 16);
        window._renderHomeWelcomeStrip?.();
    } catch(e) {}
};
 
