// Whether the current user has unlocked Anime Authority (review_50) — cached on load
window._amberAnimeAuthority = false;

// Live topbar amber balance display
window.amberUnsubscribe = null;
window._amberSubscribeTopbar = function() {
    if (!auth.currentUser) return;
    if (window.amberUnsubscribe) { window.amberUnsubscribe(); window.amberUnsubscribe = null; }
    window.amberUnsubscribe = onSnapshot(doc(db, 'profiles', auth.currentUser.uid), (snap) => {
        const data = snap.exists() ? snap.data() : {};
        window._myProfile = data;
        const amber = data.amber || 0;
        window._cachedAmber = amber;
        const badge = document.getElementById('topbar-amber-badge');
        const val = document.getElementById('topbar-amber-value');
        if (val) val.textContent = amber.toLocaleString();
        if (badge) badge.style.display = 'flex';
        const hw = document.getElementById('hw-amber');
        if (hw) hw.textContent = amber.toLocaleString();
        // Keep topbar name in sync with Firestore — this fires immediately on
        // subscribe so it always reflects the latest displayName without a
        // separate getDoc race.
        const nameEl = document.getElementById('topbar-user-name');
        if (nameEl) nameEl.textContent = data.displayName || 'WeeBee User';
        // Keep rank badge in sync — onSnapshot fires from cache then again from
        // the server, so this corrects any stale-cache Newcomer flash that
        // updateTopbarRank() may have rendered before the server responded.
        const reviewCount = data.reviewCount || 0;
        if (reviewCount !== window.myReviewCount || !document.getElementById('topbar-rank-badge')?.innerHTML) {
            window.myReviewCount = reviewCount;
            window.userRankCache[auth.currentUser.uid] = reviewCount;
            const rankEl = document.getElementById('topbar-rank-badge');
            if (rankEl) rankEl.innerHTML = window.getRankBadgeHTML(reviewCount, 16);
        }
        window._renderHomeWelcomeStrip?.();
    });
};

// Award amber to the current user
async function _awardAmber(amount, reason) {
    if (!auth.currentUser || amount <= 0) return;
    const uid = auth.currentUser.uid;
    try {
        await updateDoc(doc(db, 'profiles', uid), { amber: increment(amount) });
        addDoc(collection(db, 'amber_log'), { uid, amount, reason, timestamp: new Date() }).catch(() => {});
        _incrementUserStats({ amberEarned: amount }).catch(() => {});
    } catch(e) {}
}

async function _incrementUserStats(fields) {
    if (!auth.currentUser) return;
    const uid = auth.currentUser.uid;
    const year = new Date().getFullYear().toString();
    const updates = {};
    for (const [k, v] of Object.entries(fields)) updates[k] = increment(v);
    await Promise.all([
        setDoc(doc(db, 'user_stats', uid), updates, { merge: true }),
        setDoc(doc(db, 'user_stats', uid, 'years', year), updates, { merge: true }),
    ]);
}

// Award amber to any uid — used for likes received by post author
async function _awardAmberToUser(uid, amount, reason) {
    if (!uid || amount <= 0) return;
    await updateDoc(doc(db, 'profiles', uid), { amber: increment(amount) });
    addDoc(collection(db, 'amber_log'), { uid, amount, reason, timestamp: new Date() }).catch(() => {});
}

// Award amber for a daily-capped action (e.g. games) — fires once per key per day.
// Writes the claim flag to Firestore so _syncGameProgressFromCloud can block
// a second claim on another device.
function _awardAmberDaily(key, amount) {
    if (!auth.currentUser) return;
    const today = bwGetDate();
    const storageKey = `weebee_amber_${key}_${today}`;
    if (localStorage.getItem(storageKey)) return;
    localStorage.setItem(storageKey, '1');
    setDoc(doc(db, 'game_progress', auth.currentUser.uid), { [storageKey]: '1' }, { merge: true }).catch(() => {});
    _awardAmber(amount, key).catch(() => {});
}

// One-time bonus for a user's very first review (quick or in-depth) —
// guarded by a profile flag so deleting/re-adding a review can't re-trigger it.
async function _awardFirstReviewBonus() {
    if (!auth.currentUser) return;
    const uid = auth.currentUser.uid;
    try {
        const pd = await getDoc(doc(db, 'profiles', uid));
        if (pd.exists() && pd.data().firstReviewBonusGiven) return;
        await setDoc(doc(db, 'profiles', uid), { firstReviewBonusGiven: true }, { merge: true });
        await _awardAmber(500, 'review:first');
    } catch(e) {}
}

// Award 1 amber for an interaction (like/comment given) — max 10/day combined
function _awardAmberInteraction() {
    if (!auth.currentUser) return;
    const today = bwGetDate();
    const key = `weebee_amber_interactions_${today}`;
    const count = parseInt(localStorage.getItem(key) || '0');
    if (count >= 10) return;
    localStorage.setItem(key, count + 1);
    _awardAmber(1, 'interaction').catch(() => {});
}

// Tracks the "reacted to N posts" Social achievements — call when a user
// adds a like/dislike/agree/etc. to any post (not when removing one).
// `itemKey` uniquely identifies the post being reacted to; a given key is
// only ever counted once, so toggling a like on/off repeatedly on the same
// post can't be used to farm achievement/amber progress.
// Returns true if this was a brand-new reaction, false if `itemKey` was
// already counted previously.
async function _recordReactionGiven(itemKey) {
    if (!auth.currentUser) return false;
    const ref = doc(db, "profiles", auth.currentUser.uid);
    try {
        const pd = await getDoc(ref);
        const reacted = pd.exists() ? (pd.data().reactedItemKeys || []) : [];
        if (itemKey && reacted.includes(itemKey)) return false;
        const update = { reactionCount: increment(1) };
        if (itemKey) update.reactedItemKeys = arrayUnion(itemKey);
        await setDoc(ref, update, { merge: true });
        const newPd = await getDoc(ref);
        window.awardAchievements(window.getEarnedIds('react', newPd.exists() ? (newPd.data().reactionCount || 1) : 1)).catch(() => {});
        return true;
    } catch(e) { return false; }
}
// ── End Amber Currency System ────────────────────────────────────

window.initUserAchievements = async function() {
    if (!auth.currentUser) return;
    const uid = auth.currentUser.uid;
    try {
        const [profileDoc, achDoc, foundersDoc] = await Promise.all([
            getDoc(doc(db, "profiles", uid)),
            getDoc(doc(db, "achievements", uid)),
            getDoc(doc(db, "meta", "founders"))
        ]);
        const profile = profileDoc.exists() ? profileDoc.data() : {};
        const existing = achDoc.exists() ? achDoc.data() : {};
        window._amberAnimeAuthority = !!existing.review_50;

        const toCheck = [
            ...window.getEarnedIds('review', profile.reviewCount  || 0),
            ...window.getEarnedIds('indepth',  profile.indepthCount || 0),
            ...window.getEarnedIds('react',    profile.reactionCount|| 0),
            ...window.getEarnedIds('complete', profile.completedCount|| 0),
        ];
        if ((profile.droppedCount || 0) >= 10) toCheck.push('dropout');

        // Backfill suggestionCount for users who posted suggestions before this
        // counter existed, by counting their existing 'suggestion' reviews.
        let suggestionCount = profile.suggestionCount;
        if (suggestionCount == null) {
            const suggSnap = await getDocs(query(collection(db, "reviews"), where("uid", "==", uid), where("type", "==", "suggestion")));
            suggestionCount = suggSnap.size;
            setDoc(doc(db, "profiles", uid), { suggestionCount }, { merge: true }).catch(() => {});
        }
        toCheck.push(...window.getEarnedIds('suggestor', suggestionCount || 0));

        const founders = foundersDoc.exists() ? (foundersDoc.data().uids || []) : [];
        founders.forEach(id => window.founderUids.add(id));
        if (founders.includes(uid)) {
            toCheck.push('founder');
        } else if (founders.length < 25) {
            setDoc(doc(db, "meta", "founders"), { uids: [...founders, uid] }, { merge: true }).catch(() => {});
            toCheck.push('founder');
        }

        const followSnap = await getDocs(query(collection(db, "follows"), where("followerUid", "==", uid), where("type", "==", "user"), limit(1)));
        if (!followSnap.empty) toCheck.push('first_follow');

        const toAward = [...new Set(toCheck)].filter(id => !existing[id]);
        if (toAward.length) {
            const updates = {};
            const now = new Date();
            toAward.forEach(id => { updates[id] = { earnedAt: now }; });
            setDoc(doc(db, "achievements", uid), updates, { merge: true }).catch(() => {});
        }
    } catch(e) {}
    // Login bonus
    _awardLoginBonus().catch(() => {});
    // Check community achievements separately (Tier Lists, Feed)
    window.checkCommunityAchievements().catch(() => {});
};

async function _awardLoginBonus() {
    if (!auth.currentUser) return;
    const uid = auth.currentUser.uid;
    const today = bwGetDate();
    const yesterday = bwGetYesterday(); // capture before any await — midnight crossing would give wrong value after
    const storageKey = `weebee_amber_login_${today}`;
    if (localStorage.getItem(storageKey)) return;
    try {
        const pd = await getDoc(doc(db, 'profiles', uid));
        const p = pd.exists() ? pd.data() : {};
        const lastDate = p.lastLoginDate || null;
        if (lastDate === today) { localStorage.setItem(storageKey, '1'); return; }
        const streak = p.loginStreak || 0;
        const newStreak = lastDate === yesterday ? streak + 1 : 1;
        const bonus = 100 + Math.min((newStreak - 1) * 5, 100);
        await setDoc(doc(db, 'profiles', uid), { loginStreak: newStreak, lastLoginDate: today }, { merge: true });
        localStorage.setItem(storageKey, '1'); // set after streak write so a tab-close before amber doesn't block tomorrow's run
        await _awardAmber(bonus, `login:streak${newStreak}`);
        _incrementUserStats({ loginDays: 1 }).catch(() => {});
        _showAmberToast(bonus, newStreak);
    } catch(e) { console.error('[LoginBonus]', e); }
}

function _showAmberToast(amount, streak) {
    const toast = document.getElementById('amber-toast');
    if (!toast) return;
    document.getElementById('toast-amber-amount').textContent = `+${amount} Amber`;
    document.getElementById('toast-amber-desc').textContent = streak > 1 ? `Day ${streak} streak — keep it up!` : 'Come back tomorrow for more!';
    const ach = document.getElementById('achievement-toast');
    toast.style.bottom = (ach && ach.style.display !== 'none') ? '110px' : '24px';
    toast.style.display = 'flex';
    clearTimeout(window._amberToastTimer);
    window._amberToastTimer = setTimeout(() => { toast.style.display = 'none'; }, 4500);
}

window.checkCommunityAchievements = async function() {
    if (!auth.currentUser) return;
    const uid = auth.currentUser.uid;
    const ids = [];
    try {
        // Tier list achievements
        const tlSnap = await getDocs(query(collection(db, 'tier_lists'), where('uid', '==', uid)));
        const tlCount = tlSnap.size;
        if (tlCount >= 1) ids.push('tl_first');
        if (tlCount >= 10) ids.push('tl_10');
        tlSnap.forEach(d => { if ((d.data().likes || []).length >= 10) ids.push('tl_crowd_pleaser'); });
        // Feed trending: total likes across bw_posts
        const bwSnap = await getDocs(query(collection(db, 'bw_posts'), where('uid', '==', uid)));
        const totalLikes = bwSnap.docs.reduce((sum, d) => sum + (d.data().likes || []).length, 0);
        if (totalLikes >= 25) ids.push('feed_trending');
        // BuzzWord leaderboard-based (in case missed during solve)
        const [opLb, nrtLb] = await Promise.all([
            getDoc(doc(db, 'bw_op_leaderboard', uid)),
            getDoc(doc(db, 'bw_nrt_leaderboard', uid))
        ]);
        if (opLb.exists()) {
            const d = opLb.data();
            if ((d.totalWins||0) >= 1)  ids.push('bwop_first');
            if ((d.currentStreak||0) >= 7)  ids.push('bwop_streak_7');
            if ((d.currentStreak||0) >= 100) ids.push('bwop_streak_100');
            if ((d.totalWins||0) >= 30) ids.push('bwop_total_30');
            if (nrtLb.exists() && (nrtLb.data().totalWins||0) >= 1) ids.push('bw_multiverse');
        }
        if (nrtLb.exists()) {
            const d = nrtLb.data();
            if ((d.totalWins||0) >= 1)  ids.push('bwnrt_first');
            if ((d.currentStreak||0) >= 7)  ids.push('bwnrt_streak_7');
            if ((d.totalWins||0) >= 30) ids.push('bwnrt_total_30');
        }
        // Hot Takes achievements
        const htSnap = await getDocs(query(collection(db, 'hot_takes'), where('uid', '==', uid)));
        if (htSnap.size >= 1)  ids.push('ht_first');
        if (htSnap.size >= 10) ids.push('ht_10');
        htSnap.forEach(d => {
            const data = d.data();
            if ((data.agreeUids||[]).length >= 25) ids.push('ht_popular');
            if ((data.disagreeUids||[]).length >= 10) ids.push('ht_controversial');
        });
        // Polls achievements
        const pollsSnap = await getDocs(query(collection(db, 'polls'), where('uid', '==', uid)));
        if (pollsSnap.size >= 1) ids.push('poll_first');
        pollsSnap.forEach(d => {
            const totalVotes = (d.data().options||[]).reduce((sum, o) => sum + (o.voters||[]).length, 0);
            if (totalVotes >= 20) ids.push('poll_popular');
        });
    } catch(e) {}
    if (ids.length) window.awardAchievements(ids).catch(() => {});
};

window.loadProfileAchievements = async function(uid) {
    const container = document.getElementById('achievements-grid-container');
    if (!container || !uid) return;
    container.innerHTML = '<div class="loading">Loading achievements...</div>';
    try {
        const achDoc = await getDoc(doc(db, "achievements", uid));
        const earned = achDoc.exists() ? achDoc.data() : {};
        const cats = ['Critic', 'Social', 'Collector', 'Special', 'Community'];
        const fmtDate = ts => { try { const d = ts?.toDate ? ts.toDate() : new Date(ts); return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }); } catch(e) { return null; }};
        const achCard = (ach) => {
            const isEarned = !!earned[ach.id];
            const date = isEarned ? fmtDate(earned[ach.id]?.earnedAt) : null;
            return `<div class="achievement-card ${isEarned ? 'earned' : 'locked'}" title="${ach.name}: ${ach.desc}">
                <span class="material-symbols-outlined ach-icon" style="${isEarned ? `color:${ach.color}` : ''}">${ach.icon}</span>
                <div class="ach-name">${ach.name}</div>
                <div class="ach-desc">${ach.desc}</div>
                ${isEarned && ach.perk ? `<div class="ach-perk" style="font-size:11px;font-weight:700;color:#f59e0b;margin-top:4px;">🟡 ${ach.perk}</div>` : ''}
                ${date ? `<div class="ach-date">${date}</div>` : ''}
            </div>`;
        };
        let html = '';
        cats.forEach(cat => {
            const catAchs = ACHIEVEMENTS.filter(a => a.cat === cat);
            const earnedCount = catAchs.filter(a => earned[a.id]).length;
            html += `<div style="margin-bottom:28px;">
                <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:14px;">
                    <h4 style="font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:1.5px; color:var(--text-muted);">${cat}</h4>
                    <span style="font-size:11px; color:var(--text-muted);">${earnedCount} / ${catAchs.length}</span>
                </div>`;
            if (cat === 'Community') {
                const subcats = [...new Set(catAchs.map(a => a.subcat || 'General'))];
                subcats.forEach(sc => {
                    const scAchs = catAchs.filter(a => (a.subcat || 'General') === sc);
                    const scEarned = scAchs.filter(a => earned[a.id]).length;
                    html += `<div style="margin-bottom:22px;">
                        <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:10px; padding-bottom:6px; border-bottom:1px solid var(--border-color);">
                            <span style="font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:1px; color:var(--text-muted);">${sc}</span>
                            <span style="font-size:11px; color:var(--text-muted);">${scEarned} / ${scAchs.length}</span>
                        </div>
                        <div class="achievement-grid">${scAchs.map(achCard).join('')}</div>
                    </div>`;
                });
            } else {
                html += `<div class="achievement-grid">${catAchs.map(achCard).join('')}</div>`;
            }
            html += `</div>`;
        });
        container.innerHTML = html;
    } catch(e) { container.innerHTML = '<p style="color:var(--text-muted); font-size:13px; text-align:center;">Failed to load achievements.</p>'; }
};

