// --- Detail Page Tabs ---
window.switchDetailTabById = function(tabId) {
    const detailMain = document.querySelector('.detail-main');
    if (!detailMain) return;
    detailMain.querySelectorAll('.detail-tab').forEach(t => t.classList.remove('active'));
    detailMain.querySelectorAll('.detail-tab-content').forEach(c => c.style.display = 'none');
    const tabBtn = detailMain.querySelector(`.detail-tab[onclick*="${tabId}"]`);
    if (tabBtn) tabBtn.classList.add('active');
    const content = document.getElementById(tabId);
    if (content) content.style.display = 'block';
};

window.switchDetailTab = function(event, tabId) {
    const detailMain = event.target.closest('.detail-main');
    detailMain.querySelectorAll('.detail-tab').forEach(t => t.classList.remove('active'));
    detailMain.querySelectorAll('.detail-tab-content').forEach(c => c.style.display = 'none');
    event.target.classList.add('active');
    const content = document.getElementById(tabId);
    content.style.display = 'block';
    if (tabId === 'tab-episodes' && !content.dataset.loaded) {
        content.dataset.loaded = 'true';
        fetchDetailEpisodes(window.currentAnimeId);
    }
    if (tabId === 'tab-seasons' && !content.dataset.loaded) {
        content.dataset.loaded = 'true';
        window.loadAnimeRelations(window.currentAnimeId);
    }
};

window.loadAnimeRelations = async function(mal_id) {
    const container = document.getElementById('tab-seasons');
    container.innerHTML = '<div class="loading">Loading related media...</div>';
    try {
        const allEntries = new Map(); // mal_id → entry object
        const visited = new Set([parseInt(mal_id), mal_id]);
        const chainQueue = []; // sequel/prequel ids to follow

        // Fetch relations for a given id and collect entries
        async function fetchAndCollect(id) {
            const { data } = await window.jikanFetch(
                `https://api.jikan.moe/v4/anime/${id}/relations`, `relations_${id}`
            );
            (data || []).forEach(rel => {
                rel.entry.forEach(e => {
                    if (e.type !== 'anime' || visited.has(e.mal_id)) return;
                    visited.add(e.mal_id);
                    allEntries.set(e.mal_id, { ...e, relation: rel.relation });
                    if (['Sequel', 'Prequel'].includes(rel.relation)) {
                        chainQueue.push(e.mal_id);
                    }
                });
            });
        }

        // Step 1: get direct relations
        await fetchAndCollect(mal_id);

        // Step 2: follow sequel/prequel chain until exhausted (max 15 hops)
        let hops = 0;
        while (chainQueue.length > 0 && hops < 15) {
            const nextId = chainQueue.shift();
            hops++;
            await new Promise(r => setTimeout(r, 420));
            try { await fetchAndCollect(nextId); } catch(_) {}
        }

        const entries = [...allEntries.values()];
        if (entries.length === 0) {
            container.innerHTML = '<p style="color:var(--text-muted); text-align:center; padding:30px; font-size:14px;">No related anime found.</p>';
            return;
        }

        // Sort: sequels/prequels first, then other relations
        const relOrder = { 'Prequel': 0, 'Sequel': 1, 'Parent story': 2, 'Full story': 3, 'Side story': 4, 'Other': 5 };
        entries.sort((a, b) => (relOrder[a.relation] ?? 6) - (relOrder[b.relation] ?? 6));

        container.innerHTML = entries.map(e => `
            <div style="display:flex; align-items:center; gap:14px; padding:12px; border-radius:10px; background:var(--bg-gray); margin-bottom:8px; cursor:pointer;" onclick="loadAnimeDetails(${e.mal_id})">
                <div style="width:50px; height:70px; border-radius:6px; background:var(--bg-gray-darker); flex-shrink:0; overflow:hidden;">
                    <img id="rel-img-${e.mal_id}" src="" style="width:100%; height:100%; object-fit:cover; display:none;">
                </div>
                <div style="flex:1; min-width:0;">
                    <div style="font-weight:600; font-size:14px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${e.name}</div>
                    <div style="font-size:12px; color:var(--text-muted); margin-top:4px;">${e.relation}</div>
                </div>
                <span class="material-symbols-outlined" style="color:var(--text-muted); flex-shrink:0;">chevron_right</span>
            </div>`).join('');

        // Load cover images progressively
        for (const e of entries) {
            await new Promise(r => setTimeout(r, 420));
            try {
                const { data: d } = await window.jikanFetch(`https://api.jikan.moe/v4/anime/${e.mal_id}`, `full_${e.mal_id}`);
                const img = document.getElementById(`rel-img-${e.mal_id}`);
                if (img && d?.images?.jpg?.image_url) { img.src = d.images.jpg.image_url; img.style.display = 'block'; }
            } catch(_) {}
        }
    } catch(e) {
        container.innerHTML = '<p style="color:var(--text-muted); text-align:center; padding:30px; font-size:14px;">Failed to load related media.</p>';
    }
};

// ── Filler Guide helpers ──────────────────────────────────────────────────────

// Maps our internal type key → display label + colors
const FILLER_TYPE_META = {
    manga_canon:  { label: 'Manga Canon',        border: '#22c55e', bg: 'rgba(34,197,94,0.08)',   tag: '#22c55e' },
    anime_canon:  { label: 'Anime Canon',         border: '#3b82f6', bg: 'rgba(59,130,246,0.08)',  tag: '#3b82f6' },
    canon:        { label: 'Canon',               border: '#22c55e', bg: 'rgba(34,197,94,0.08)',   tag: '#22c55e' },
    mixed:        { label: 'Mixed Canon/Filler',  border: '#f59e0b', bg: 'rgba(245,158,11,0.08)',  tag: '#f59e0b' },
    filler:       { label: 'Filler',              border: '#ef4444', bg: 'rgba(239,68,68,0.08)',   tag: '#ef4444' },
    recap:        { label: 'Recap',               border: '#8b5cf6', bg: 'rgba(139,92,246,0.08)',  tag: '#8b5cf6' },
};

// Converts a flat list of episode numbers into a compact range string: "1-3, 5, 7-10"
function _fillerNums2Ranges(nums) {
    if (!nums.length) return '';
    const sorted = [...new Set(nums)].sort((a, b) => a - b);
    const ranges = [];
    let start = sorted[0], end = sorted[0];
    for (let i = 1; i < sorted.length; i++) {
        if (sorted[i] === end + 1) { end = sorted[i]; }
        else { ranges.push(start === end ? `${start}` : `${start}-${end}`); start = end = sorted[i]; }
    }
    ranges.push(start === end ? `${start}` : `${start}-${end}`);
    return ranges.join(', ');
}

// Normalizes an anime title for fuzzy matching against filler_guide titleNorms
function _fillerNormTitle(t) {
    return (t || '')
        .toLowerCase()
        .replace(/[:\-–—!?.,'"()[\]]/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
}

// Looks up filler data from our Firestore filler_guide collection.
// Tries each normalized title variant; returns null if not found.
async function _fillerLookup(anime) {
    const candidates = [
        anime.title,
        anime.title_english,
        anime.title_japanese,
    ].filter(Boolean).map(_fillerNormTitle).filter((v, i, a) => v && a.indexOf(v) === i);

    for (const norm of candidates) {
        try {
            const snap = await getDocs(
                query(collection(db, 'filler_guide'), where('titleNorms', 'array-contains', norm), limit(1))
            );
            if (!snap.empty) return snap.docs[0].data();
        } catch(e) {}
    }
    return null;
}

// Renders the filler summary block (ranges per type) at the top
function _fillerRenderSummary(fillerMap) {
    // Group episode numbers by type
    const byType = {};
    for (const [epNum, type] of Object.entries(fillerMap)) {
        if (!byType[type]) byType[type] = [];
        byType[type].push(parseInt(epNum));
    }

    // Render order: canon types first, then mixed, then filler, then recap
    const order = ['manga_canon', 'anime_canon', 'canon', 'mixed', 'filler', 'recap'];
    const rows = order
        .filter(t => byType[t]?.length)
        .map(t => {
            const meta = FILLER_TYPE_META[t];
            const ranges = _fillerNums2Ranges(byType[t]);
            return `<div style="display:flex;align-items:baseline;gap:10px;margin-bottom:6px;flex-wrap:wrap;">
                <span style="display:inline-block;padding:2px 8px;border-radius:4px;font-size:11px;font-weight:700;color:white;background:${meta.tag};white-space:nowrap;flex-shrink:0;">${meta.label}</span>
                <span style="font-size:13px;color:var(--text-dark);line-height:1.5;">${ranges}</span>
            </div>`;
        }).join('');

    if (!rows) return '';
    return `<div style="background:var(--bg-gray);border-radius:10px;padding:14px 16px;margin-bottom:18px;">
        <div style="font-size:12px;font-weight:600;color:var(--text-muted);text-transform:uppercase;letter-spacing:.05em;margin-bottom:10px;">Episode Guide</div>
        ${rows}
        <div style="font-size:11px;color:var(--text-muted);margin-top:10px;">Source: <a href="https://www.animefillerlist.com" target="_blank" rel="noopener" style="color:var(--text-muted);text-decoration:underline;">AnimeFillerList.com</a></div>
    </div>`;
}

// --- Episode Scoring ---
async function fetchDetailEpisodes(mal_id, page = 1) {
    const container = document.getElementById('detail-eps-container');
    if (!container) return;
    if (page === 1) {
        container.innerHTML = '<div class="loading">Loading Episodes...</div>';
        window.currentEpStats = {};
        window._fillerMap = null; // {epNum: type} from our DB, null = not loaded yet
        try {
            const epSnap = await getDocs(query(collection(db, 'episode_reviews'), where('mal_id', '==', mal_id)));
            const uid = auth.currentUser?.uid;
            epSnap.forEach(d => {
                const data = d.data(); const n = data.episode_number;
                if (!window.currentEpStats[n]) window.currentEpStats[n] = { total: 0, count: 0, userScore: null, userComment: null };
                window.currentEpStats[n].total += parseFloat(data.score);
                window.currentEpStats[n].count++;
                if (uid && data.uid === uid) { window.currentEpStats[n].userScore = data.score; window.currentEpStats[n].userComment = data.comment || ''; }
            });
        } catch(e) { console.error('Episode scores fetch error:', e); }

        // Look up filler data in parallel with the Jikan fetch below
        const animeData = window.currentAnime;
        if (animeData) {
            _fillerLookup(animeData).then(doc => {
                if (doc?.episodes?.length) {
                    window._fillerMap = {};
                    doc.episodes.forEach(ep => { window._fillerMap[ep.n] = ep.type; });
                    // Re-render the guide header + episode borders if already rendered
                    const summaryEl = document.getElementById('ep-filler-summary');
                    if (summaryEl) summaryEl.outerHTML = _fillerRenderSummary(window._fillerMap);
                    // Refresh border colors on already-rendered rows
                    document.querySelectorAll('.episode-row[data-ep]').forEach(row => {
                        const n = parseInt(row.dataset.ep);
                        const type = window._fillerMap[n];
                        if (type) {
                            const meta = FILLER_TYPE_META[type];
                            row.style.borderLeftColor = meta.border;
                            row.style.background = meta.bg;
                            const tag = row.querySelector('.ep-filler-tag');
                            if (tag) { tag.textContent = meta.label; tag.style.color = meta.tag; tag.style.display = ''; }
                        }
                    });
                }
            }).catch(() => {});
        }
    }

    try {
        const json = await window.jikanFetch(`https://api.jikan.moe/v4/anime/${mal_id}/episodes?page=${page}`, `eps_${mal_id}_p${page}`, JIKAN_CAROUSEL_TTL_MS);
        const episodes = json.data || [];
        const hasNext = json.pagination?.has_next_page;
        if (page === 1) window.currentEpisodeList = [];
        window.currentEpisodeList.push(...episodes);
        if (episodes.length === 0 && page === 1) {
            container.innerHTML = '<p style="color:var(--text-muted);text-align:center;padding:30px 0;">No episode data available for this anime yet.</p>';
            return;
        }

        const renderRows = (eps) => eps.map(ep => {
            const stats = window.currentEpStats[ep.mal_id] || {};
            const avg = stats.count > 0 ? (stats.total / stats.count).toFixed(1) : null;
            const userScore = stats.userScore;

            // Filler type: prefer our DB, fall back to Jikan booleans
            let type = window._fillerMap?.[ep.mal_id];
            if (!type && ep.filler)  type = 'filler';
            if (!type && ep.recap)   type = 'recap';
            const meta = type ? FILLER_TYPE_META[type] : null;

            const borderStyle = meta ? `border-left:3px solid ${meta.border};background:${meta.bg};` : '';
            const tagHtml = `<span class="ep-filler-tag" style="font-size:11px;font-weight:600;color:${meta?.tag || 'transparent'};display:${meta ? 'inline' : 'none'};">${meta?.label || ''}</span>`;

            return `<div class="episode-row" id="ep-row-${ep.mal_id}" data-ep="${ep.mal_id}" style="${borderStyle}">
                <div class="ep-num">${ep.mal_id}</div>
                <div class="ep-info">
                    <strong class="ep-title" title="${(ep.title || '').replace(/"/g, '&quot;')}">${ep.title || `Episode ${ep.mal_id}`}</strong>
                    <span class="ep-meta">${ep.aired ? new Date(ep.aired).toLocaleDateString() : 'TBA'} ${tagHtml}</span>
                </div>
                <div class="ep-score-area">
                    ${avg ? `<span class="ep-avg">WeeBee ${avg}</span>` : ''}
                    <button class="ep-score-btn${userScore ? ' scored' : ''}" onclick="openEpisodeScoreModal(${mal_id}, ${ep.mal_id})">${userScore ? `${userScore} ✓` : 'Score'}</button>
                    <button class="ep-score-btn" id="ep-discuss-btn-${ep.mal_id}" onclick="window.toggleEpisodeDiscussion(${mal_id}, ${ep.mal_id})">💬</button>
                </div>
            </div>
            <div id="ep-discuss-${ep.mal_id}" style="display:none;"></div>`;
        }).join('');

        if (page === 1) {
            const summaryHtml = window._fillerMap ? _fillerRenderSummary(window._fillerMap)
                : `<div id="ep-filler-summary"></div>`; // placeholder replaced when filler loads
            container.innerHTML = summaryHtml + `<div class="episode-list">${renderRows(episodes)}</div>`;
        } else {
            const list = container.querySelector('.episode-list');
            if (list) list.insertAdjacentHTML('beforeend', renderRows(episodes));
        }

        const oldBtn = container.querySelector('.ep-load-more');
        if (oldBtn) oldBtn.remove();
        if (hasNext) {
            const btn = document.createElement('button');
            btn.className = 'action-btn ep-load-more';
            btn.style.cssText = 'width:100%;justify-content:center;margin-top:15px;background:transparent;color:var(--text-dark);border:1px solid var(--border-color);';
            btn.textContent = 'Load More Episodes';
            btn.onclick = () => { btn.disabled = true; btn.textContent = 'Loading...'; fetchDetailEpisodes(mal_id, page + 1); };
            container.appendChild(btn);
        }
    } catch(e) {
        if (page === 1) container.innerHTML = '<p style="color:var(--text-muted);text-align:center;padding:30px 0;">Failed to load episodes. Try again later.</p>';
        console.error(e);
    }
}

// ─── Episode Discussion ───────────────────────────────────────────────────────
function renderEpisodeComment(commentId, c, malId, epNum) {
    const isOwner = auth.currentUser && c.uid === auth.currentUser.uid;
    const ownerBtns = isOwner ? `
        <button onclick="window.editEpisodeComment('${commentId}')" style="background:none;border:none;cursor:pointer;color:var(--text-muted);padding:0;display:flex;align-items:center;" title="Edit"><span class="material-symbols-outlined" style="font-size:14px;">edit</span></button>
        <button onclick="window.deleteEpisodeComment('${commentId}',${malId},${epNum})" style="background:none;border:none;cursor:pointer;color:var(--text-muted);padding:0;display:flex;align-items:center;" title="Delete"><span class="material-symbols-outlined" style="font-size:14px;">delete</span></button>` : '';
    const replyBtn = `<button onclick="window.replyToEpisodeComment(this,'${encodeURIComponent(c.displayName)}',${epNum})" style="background:none;border:none;cursor:pointer;color:var(--text-muted);padding:0;display:flex;align-items:center;" title="Reply"><span class="material-symbols-outlined" style="font-size:14px;">reply</span></button>`;
    const isReply = !!c.replyTo;
    const replyBadge = isReply ? `<div style="font-size:11px;color:var(--text-muted);margin-bottom:4px;display:flex;align-items:center;gap:3px;"><span class="material-symbols-outlined" style="font-size:12px;">subdirectory_arrow_right</span> replying to <strong style="color:var(--accent-yellow);">@${c.replyTo}</strong></div>` : '';
    const replyStyle = isReply ? 'margin-left:20px;border-left:3px solid var(--accent-yellow);' : '';
    return `<div id="ep-comment-doc-${commentId}" style="display:flex;gap:10px;margin-bottom:10px;align-items:flex-start;background:var(--bg-white);padding:10px;border-radius:8px;border:1px solid var(--border-color);${replyStyle}">
        <img src="${c.avatar || ''}" style="width:30px;height:30px;border-radius:50%;object-fit:cover;flex-shrink:0;" onerror="this.src='https://api.dicebear.com/9.x/initials/svg?seed=${encodeURIComponent(c.displayName)}&backgroundColor=ffc107&fontColor=333333'">
        <div style="flex:1;min-width:0;">
            <div style="display:flex;justify-content:space-between;align-items:center;gap:6px;">
                <strong style="font-size:13px;color:var(--text-dark);">${c.displayName}</strong>
                <div style="display:flex;gap:4px;">${replyBtn}${ownerBtns}</div>
            </div>
            ${replyBadge}
            <p id="ep-comment-text-${commentId}" style="font-size:13px;margin:2px 0 0;color:var(--text-dark);word-break:break-word;">${c.text}${c.edited ? ' <span style="font-size:10px;color:var(--text-muted);font-style:italic;">(edited)</span>' : ''}</p>
        </div>
    </div>`;
}

window.replyToEpisodeComment = function(btn, encodedName, epNum) {
    const name = decodeURIComponent(encodedName);
    const input = document.getElementById(`ep-comment-input-${epNum}`);
    if (!input) return;
    input.dataset.replyTo = name;
    input.value = `@${name} `;
    input.focus();
    input.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
};

window.toggleEpisodeDiscussion = async function(malId, epNum) {
    const panel = document.getElementById(`ep-discuss-${epNum}`);
    const btn = document.getElementById(`ep-discuss-btn-${epNum}`);
    if (!panel) return;

    const isOpen = panel.style.display !== 'none';
    panel.style.display = isOpen ? 'none' : 'block';
    if (btn) btn.style.color = isOpen ? '' : 'var(--accent-yellow)';
    if (isOpen || panel.dataset.loaded) return;

    panel.dataset.loaded = '1';
    panel.innerHTML = '<div style="padding:12px;color:var(--text-muted);font-size:13px;">Loading discussion...</div>';
    panel.style.cssText = 'display:block;background:var(--bg-gray);border-radius:0 0 10px 10px;padding:14px;margin-bottom:2px;';

    try {
        const snap = await getDocs(query(
            collection(db, 'episode_comments'),
            where('mal_id', '==', malId),
            where('episode', '==', epNum)
        ));
        const comments = snap.docs.map(d => ({ _id: d.id, ...d.data() }))
            .sort((a, b) => (a.timestamp?.toMillis?.() || 0) - (b.timestamp?.toMillis?.() || 0));

        panel.innerHTML = `
            <div id="ep-comment-list-${epNum}" style="margin-bottom:12px;">
                ${comments.length
                    ? comments.map(c => renderEpisodeComment(c._id, c, malId, epNum)).join('')
                    : '<p style="font-size:13px;color:var(--text-muted);margin:0 0 8px;">No comments yet — start the discussion!</p>'}
            </div>
            <div style="display:flex;gap:8px;">
                <input type="text" id="ep-comment-input-${epNum}" placeholder="Discuss this episode..." maxlength="500"
                    style="flex:1;padding:8px 12px;border-radius:8px;border:1px solid var(--border-color);background:var(--bg-white);color:var(--text-dark);font-size:13px;"
                    onkeydown="if(event.key==='Enter'){event.preventDefault();window.submitEpisodeComment(${malId},${epNum});}">
                <button class="action-btn" onclick="window.submitEpisodeComment(${malId},${epNum})">Post</button>
            </div>`;

        if (btn) btn.textContent = `💬 ${comments.length || ''}`.trim();
    } catch(e) {
        console.error('Episode discussion error:', e);
        delete panel.dataset.loaded;
        panel.innerHTML = `<div style="padding:8px;font-size:13px;color:var(--text-muted);">Error: ${e.message}</div>`;
    }
};

window.submitEpisodeComment = async function(malId, epNum) {
    if (!auth.currentUser) return window.openAuthModal();
    const input = document.getElementById(`ep-comment-input-${epNum}`);
    if (!input) return;
    const text = input.value.trim();
    if (!text) return;
    const replyTo = input.dataset.replyTo || null;
    delete input.dataset.replyTo;
    input.value = '';

    const pd = await getDoc(doc(db, 'profiles', auth.currentUser.uid)).catch(() => null);
    const displayName = pd?.data()?.displayName || auth.currentUser.displayName || 'User';
    const avatar = pd?.data()?.avatar || auth.currentUser.photoURL || '';

    const commentData = { mal_id: malId, episode: epNum, uid: auth.currentUser.uid, displayName, avatar, text, timestamp: serverTimestamp(), edited: false, ...(replyTo && { replyTo }) };
    try {
        const ref = await addDoc(collection(db, 'episode_comments'), commentData);
        const listEl = document.getElementById(`ep-comment-list-${epNum}`);
        if (listEl) {
            listEl.querySelector('p')?.remove();
            listEl.innerHTML += renderEpisodeComment(ref.id, { ...commentData, timestamp: null }, malId, epNum);
        }
        const btn = document.getElementById(`ep-discuss-btn-${epNum}`);
        if (btn) {
            const cur = parseInt(btn.textContent.replace('💬','').trim()) || 0;
            btn.textContent = `💬 ${cur + 1}`;
        }
    } catch(e) { console.error(e); alert('Failed to post comment.'); }
};

window.deleteEpisodeComment = async function(commentId, malId, epNum) {
    if (!auth.currentUser || !confirm('Delete this comment?')) return;
    try {
        await deleteDoc(doc(db, 'episode_comments', commentId));
        document.getElementById(`ep-comment-doc-${commentId}`)?.remove();
        const btn = document.getElementById(`ep-discuss-btn-${epNum}`);
        if (btn) {
            const cur = parseInt(btn.textContent.replace('💬','').trim()) || 1;
            btn.textContent = cur - 1 > 0 ? `💬 ${cur - 1}` : '💬';
        }
    } catch(e) { alert('Failed to delete comment.'); }
};

window.editEpisodeComment = function(commentId) {
    const p = document.getElementById(`ep-comment-text-${commentId}`);
    if (!p) return;
    const current = p.textContent.replace(' (edited)', '').trim();
    const input = document.createElement('input');
    input.type = 'text'; input.value = current;
    input.style.cssText = 'width:100%;padding:4px 8px;border-radius:6px;border:1px solid var(--border-color);background:var(--bg-gray);color:var(--text-dark);font-size:13px;box-sizing:border-box;';
    const save = async () => {
        const newText = input.value.trim();
        if (!newText || newText === current) { p.style.display = ''; input.replaceWith(p); return; }
        try {
            await updateDoc(doc(db, 'episode_comments', commentId), { text: newText, edited: true });
            p.innerHTML = `${newText} <span style="font-size:10px;color:var(--text-muted);font-style:italic;">(edited)</span>`;
        } catch(e) { alert('Failed to edit.'); }
        p.style.display = ''; input.replaceWith(p);
    };
    input.onblur = save;
    input.onkeydown = e => { if (e.key === 'Enter') { e.preventDefault(); save(); } if (e.key === 'Escape') { input.replaceWith(p); p.style.display = ''; } };
    p.style.display = 'none'; p.after(input); input.focus(); input.select();
};

window.openEpisodeScoreModal = function(mal_id, ep_number) {
    if (!auth.currentUser) return window.openAuthModal();
    window.currentEpisodeContext = { mal_id, ep_number };
    const ep = window.currentEpisodeList?.find(e => e.mal_id === ep_number);
    document.getElementById('ep-modal-title').textContent = `Episode ${ep_number}`;
    document.getElementById('ep-modal-subtitle').textContent = ep?.title || '';
    const stats = window.currentEpStats?.[ep_number] || {};
    document.getElementById('ep-score-input').value = stats.userScore || '';
    document.getElementById('ep-score-comment').value = stats.userComment || '';
    document.getElementById('ep-submit-btn').textContent = stats.userScore ? 'Update Score' : 'Save Score';
    document.getElementById('ep-delete-btn').style.display = stats.userScore ? 'inline-flex' : 'none';
    document.getElementById('episode-score-modal').style.display = 'flex';
};

window.submitEpisodeScore = async function() {
    if (!auth.currentUser) return;
    const { mal_id, ep_number } = window.currentEpisodeContext;
    const scoreVal = parseFloat(document.getElementById('ep-score-input').value);
    const comment = document.getElementById('ep-score-comment').value.trim();
    if (isNaN(scoreVal) || scoreVal < 1 || scoreVal > 10) return alert('Please enter a score between 1 and 10.');
    const score = parseFloat(scoreVal.toFixed(1));
    const uid = auth.currentUser.uid;
    const ep = window.currentEpisodeList?.find(e => e.mal_id === ep_number);
    await setDoc(doc(db, 'episode_reviews', `${uid}_${mal_id}_${ep_number}`), {
        mal_id, episode_number: ep_number, episode_title: ep?.title || `Episode ${ep_number}`,
        uid, username: auth.currentUser.displayName,
        avatar: auth.currentUser.photoURL || `https://api.dicebear.com/9.x/initials/svg?seed=${encodeURIComponent(auth.currentUser.displayName)}&backgroundColor=ffc107&fontColor=333333`,
        score, comment, timestamp: new Date()
    });
    if (!window.currentEpStats[ep_number]) window.currentEpStats[ep_number] = { total: 0, count: 0, userScore: null, userComment: null };
    const stats = window.currentEpStats[ep_number];
    if (stats.userScore !== null) { stats.total = stats.total - parseFloat(stats.userScore) + score; }
    else { stats.total += score; stats.count++; }
    stats.userScore = score; stats.userComment = comment;
    updateEpisodeRowDOM(mal_id, ep_number);
    window.closeAllModals();
};

window.deleteEpisodeScore = async function() {
    if (!auth.currentUser) return;
    const { mal_id, ep_number } = window.currentEpisodeContext;
    const uid = auth.currentUser.uid;
    await deleteDoc(doc(db, 'episode_reviews', `${uid}_${mal_id}_${ep_number}`));
    const stats = window.currentEpStats[ep_number];
    if (stats?.userScore !== null) { stats.total -= parseFloat(stats.userScore); stats.count--; stats.userScore = null; stats.userComment = null; }
    updateEpisodeRowDOM(mal_id, ep_number);
    window.closeAllModals();
};

function updateEpisodeRowDOM(mal_id, ep_number) {
    const row = document.getElementById(`ep-row-${ep_number}`);
    if (!row) return;
    const stats = window.currentEpStats[ep_number] || {};
    const avg = stats.count > 0 ? (stats.total / stats.count).toFixed(1) : null;
    const userScore = stats.userScore;
    row.querySelector('.ep-score-area').innerHTML = `
        ${avg ? `<span class="ep-avg">WeeBee ${avg}</span>` : ''}
        <button class="ep-score-btn${userScore ? ' scored' : ''}" onclick="openEpisodeScoreModal(${mal_id}, ${ep_number})">${userScore ? `${userScore} ✓` : 'Score'}</button>`;
}

window.onload = function() {
    const _initHash = window.location.hash.replace('#', '');
    history.replaceState({ view: 'home-view', profileUid: null, animeId: null }, '', window.location.pathname);
    const loadTrending = async () => {
        try {
            const r = await fetch('https://api.jikan.moe/v4/seasons/now?limit=15'); const d = await r.json();
            const c = document.getElementById('trending-carousel'); c.innerHTML = '';
            const seen = new Set();
            if(d.data) d.data.forEach(a => {
                if (seen.has(a.mal_id)) return;
                seen.add(a.mal_id);
                c.innerHTML += `<div class="anime-card" onclick="loadAnimeDetails(${a.mal_id})"><img src="${a.images.jpg.image_url}"><p>${a.title_english || a.title}</p></div>`;
            });
        } catch(e) { console.error("Trending error:", e); }
    };
    loadTrending(); fetchHomepageReviews();

    const _hashToView = { 'discover': 'discover-view', 'mylist': 'my-list-view', 'news': 'news-view', 'community': 'community-view', 'games': 'games-view' };
    if (_initHash === 'trivia') {
        window.goToTriviaTab();
    } else if (_initHash === 'melobee') {
        window.goToMeloBeeTab();
    } else if (_initHash && _hashToView[_initHash]) {
        switchView(_hashToView[_initHash]);
    }
};

