// --- Infinite Scroll for Home Feed ---
const _mainContent = document.querySelector('.main-content');
const _feedObserver = new IntersectionObserver((entries) => {
    if (entries[0].isIntersecting && window.currentActiveViewId === 'home-view') {
        renderActivityBatch();
    }
}, { root: _mainContent, rootMargin: '200px' });

const _sentinel = document.getElementById('home-activity-sentinel');
if (_sentinel) _feedObserver.observe(_sentinel);

// Returns today's date in America/New_York (resets at midnight EST/EDT)
function bwGetDate() {
    return new Date().toLocaleDateString('en-CA', { timeZone: 'America/New_York' });
}

// Returns yesterday's date in America/New_York (for streak comparisons).
// Uses calendar arithmetic on today's Eastern date string so DST transitions
// (where a day is 23 or 25 hours) never produce the wrong date.
function bwGetYesterday() {
    const [y, m, d] = bwGetDate().split('-').map(Number);
    return new Date(Date.UTC(y, m - 1, d - 1)).toISOString().slice(0, 10);
}

// Resolves a saved guesses array back into character objects.
// Supports both the new format (full character snapshots, immune to later
// edits/removals in the source character array) and the legacy format
// (plain id strings, resolved against the current character array).
function _bwResolveGuesses(saved, chars) {
    return (saved || []).map(g => (typeof g === 'string') ? chars.find(c => c.id === g) : g).filter(Boolean);
}

// Applies a saved daily game record to a BW state object. Older saves stored guesses
// as plain ID strings, which can fail to resolve if the character pool changes between
// site updates. When that happens the corrupted day's record is reset (locally and in
// Firestore) so the puzzle can be replayed cleanly instead of showing partial progress.
function _bwApplyDailySave(state, d, chars, storageKey, gamesCollection, today) {
    const raw = d.guesses || [];
    const resolved = _bwResolveGuesses(raw, chars);
    if (raw.length > 0 && resolved.length < raw.length) {
        state.guesses = [];
        state.solved = false;
        try { localStorage.removeItem(`${storageKey}_${today}`); } catch (_) {}
        if (auth.currentUser && gamesCollection) {
            setDoc(doc(db, gamesCollection, `${auth.currentUser.uid}_${today}`), { guesses: [], solved: false, date: today, guessCount: 0 }).catch(() => {});
        }
        return;
    }
    state.guesses = resolved;
    state.solved = d.solved || false;
}

// Computes a BuzzWord game's status line for the Community page tile from
// the locally-cached daily save (kept in sync via _saveGameState), so it
// reflects today's progress even before the game modal has been opened.
function _bwTileStatus(storageKey, today, emptyText) {
    try {
        const saved = localStorage.getItem(`${storageKey}_${today}`);
        if (saved) {
            const d = JSON.parse(saved);
            const count = (d.guesses || []).length;
            if (d.solved) return `✓ Solved in ${count} ${count === 1 ? 'guess' : 'guesses'} today!`;
            if (count > 0) return `${count} ${count === 1 ? 'guess' : 'guesses'} so far`;
        }
    } catch (_) {}
    return emptyText;
}

// Fetches the user's current streak from a BuzzWord leaderboard collection and fills in the placeholder element
window._bwShowStreak = async function(leaderboardCollection, elId) {
    if (!auth.currentUser) return;
    try {
        const snap = await getDoc(doc(db, leaderboardCollection, auth.currentUser.uid));
        const streak = snap.exists() ? (snap.data().currentStreak || 0) : 0;
        const el = document.getElementById(elId);
        if (el && streak > 0) el.innerHTML = `🔥 ${streak} day${streak === 1 ? '' : 's'} streak`;
    } catch(e) {}
};

// Returns days elapsed since 2025-01-01 — used to cycle through the fixed character order
function bwDayIndex(dateStr) {
    const [y, m, d] = dateStr.split('-').map(Number);
    return Math.floor((Date.UTC(y, m - 1, d, 12) - Date.UTC(2025, 0, 1, 12)) / 86400000);
}

// Cache for each game's stable shuffled order (computed once, reused)
const _bwOrders = {};
function bwGetOrder(key, chars, fixedSeed) {
    if (!_bwOrders[key]) _bwOrders[key] = bwSeededShuffle([...chars], fixedSeed);
    return _bwOrders[key];
}

// Deterministic shuffle — same seed produces same order every time
function bwSeededShuffle(arr, seed) {
    const a = [...arr];
    let s = seed;
    for (let i = a.length - 1; i > 0; i--) {
        s = (s * 1664525 + 1013904223) & 0xffffffff;
        const j = Math.abs(s) % (i + 1);
        [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
}

// --- ADVANCED ANIME SEARCH ---
let _advPage = 1;
let _advHasMore = false;
let _advLastParams = null;

window.openAdvancedSearch = function() {
    document.getElementById('advanced-search-modal').style.display = 'flex';
    document.getElementById('adv-search-main-view').style.display = 'flex';
    document.getElementById('adv-archive-view').style.display = 'none';
    document.getElementById('adv-search-input').focus();
};

window.closeAdvancedSearch = function() {
    document.getElementById('advanced-search-modal').style.display = 'none';
};

// Genre chip toggle
document.getElementById('adv-genre-chips')?.addEventListener('click', e => {
    const chip = e.target.closest('.adv-genre-chip');
    if (!chip) return;
    chip.classList.toggle('selected');
});

window.runAdvancedSearch = async function(loadMore = false) {
    const q = document.getElementById('adv-search-input').value.trim();
    const type = document.getElementById('adv-type-filter').value;
    const status = document.getElementById('adv-status-filter').value;
    const minScore = document.getElementById('adv-score-filter').value;
    const orderBy = document.getElementById('adv-sort-filter').value;
    const selectedGenres = [...document.querySelectorAll('.adv-genre-chip.selected')].map(c => c.dataset.genreId);

    if (!q && !selectedGenres.length && !type && !status && !minScore) {
        document.getElementById('adv-search-results').innerHTML = `<div style="text-align:center;color:var(--text-muted);padding:40px;grid-column:1/-1;">Enter a search term or select at least one filter.</div>`;
        return;
    }

    const resultsEl = document.getElementById('adv-search-results');
    const countEl = document.getElementById('adv-results-count');
    const loadMoreBtn = document.getElementById('adv-load-more-btn');

    if (!loadMore) {
        _advPage = 1;
        resultsEl.innerHTML = `<div style="text-align:center;padding:40px;grid-column:1/-1;" class="loading">Searching...</div>`;
        countEl.textContent = '';
        loadMoreBtn.style.display = 'none';
        _advLastParams = { q, type, status, minScore, orderBy, selectedGenres };
    } else {
        _advPage++;
    }

    const params = loadMore ? _advLastParams : { q, type, status, minScore, orderBy, selectedGenres };

    const urlParams = new URLSearchParams();
    if (params.q) urlParams.set('q', params.q);
    if (params.type) urlParams.set('type', params.type);
    if (params.status) urlParams.set('status', params.status);
    if (params.minScore) urlParams.set('min_score', params.minScore);
    urlParams.set('order_by', params.orderBy || 'score');
    urlParams.set('sort', 'desc');
    if (params.selectedGenres.length) urlParams.set('genres', params.selectedGenres.join(','));
    urlParams.set('limit', '24');
    urlParams.set('page', _advPage);

    const endpoint = `https://api.jikan.moe/v4/anime?${urlParams.toString()}&sfw=true`;

    try {
        const rawRes = await fetch(endpoint);
        if (!rawRes.ok) throw new Error(`Jikan ${rawRes.status}`);
        const res = await rawRes.json();
        const items = res.data || [];
        _advHasMore = res.pagination?.has_next_page || false;

        if (!loadMore) {
            if (!items.length) {
                resultsEl.innerHTML = `<div style="text-align:center;color:var(--text-muted);padding:40px;grid-column:1/-1;">No anime found. Try different filters.</div>`;
                countEl.textContent = '';
                return;
            }
            resultsEl.innerHTML = '';
        }

        const myList = await _advGetMyList();
        items.forEach(anime => {
            const inList = myList.has(String(anime.mal_id));
            const card = document.createElement('div');
            card.className = 'adv-anime-card';
            const score = anime.score ? `⭐ ${anime.score}` : '';
            const epInfo = anime.type === 'Movie' ? 'Movie' : (anime.episodes ? `${anime.episodes} eps` : anime.type || '');
            card.innerHTML = `
                <div class="adv-anime-card-img">
                    <img src="${anime.images?.jpg?.large_image_url || anime.images?.jpg?.image_url || ''}" alt="${anime.title}" loading="lazy" onerror="this.parentElement.style.background='var(--bg-gray-darker)';">
                </div>
                <div class="adv-anime-card-body">
                    <div class="adv-anime-card-title">${anime.title}</div>
                    <div class="adv-anime-card-meta">${epInfo}</div>
                    ${score ? `<div class="adv-anime-card-score">${score}</div>` : ''}
                    <button class="adv-quick-add-btn search-quick-add ${inList ? 'in-list' : ''}"
                        data-mal="${anime.mal_id}"
                        data-img="${anime.images?.jpg?.large_image_url || anime.images?.jpg?.image_url || ''}"
                        onclick="event.stopPropagation(); advQuickAdd(this, ${anime.mal_id}, '${anime.title.replace(/'/g,"\\'")}')">
                        ${inList ? 'In List' : '+ Add'}
                    </button>
                </div>`;
            card.querySelector('.adv-anime-card-img').addEventListener('click', () => loadAnimeDetails(anime.mal_id));
            card.querySelector('.adv-anime-card-title').addEventListener('click', () => loadAnimeDetails(anime.mal_id));
            resultsEl.appendChild(card);
        });

        const total = res.pagination?.items?.total;
        if (!loadMore && total) countEl.textContent = `${total.toLocaleString()} results`;
        loadMoreBtn.style.display = _advHasMore ? 'inline-flex' : 'none';

    } catch(e) {
        if (!loadMore) resultsEl.innerHTML = `<div style="text-align:center;color:var(--text-muted);padding:40px;grid-column:1/-1;">Search failed. Please try again.</div>`;
        console.error('Advanced search error:', e);
    }
};

// Cache my list IDs for quick-add checks
let _advMyListCache = null;
async function _advGetMyList() {
    if (_advMyListCache) return _advMyListCache;
    if (!auth.currentUser) return new Set();
    try {
        const snap = await getDocs(query(collection(db, 'anime_lists'), where('uid', '==', auth.currentUser.uid)));
        _advMyListCache = new Set(snap.docs.map(d => String(d.data().mal_id)));
        return _advMyListCache;
    } catch(e) { return new Set(); }
}

auth.onAuthStateChanged(() => { _advMyListCache = null; });

window.advQuickAdd = async function(btn, mal_id, title) {
    if (!auth.currentUser) { alert('Sign in to add anime to your list.'); return; }
    if (btn.classList.contains('in-list')) return;

    // Close any already-open status dropdown
    document.querySelectorAll('.adv-status-dropdown').forEach(d => d.remove());

    const image = btn.dataset.img || '';

    const STATUSES = [
        { label: 'Currently Watching', value: 'watching' },
        { label: 'Completed',          value: 'completed' },
        { label: 'On Hold',            value: 'on-hold' },
        { label: 'Dropped',            value: 'dropped' },
        { label: 'Plan to Watch',      value: 'plan-to-watch' },
    ];

    const dropdown = document.createElement('div');
    dropdown.className = 'adv-status-dropdown';
    const rect = btn.getBoundingClientRect();
    const dropHeight = STATUSES.length * 40 + 12;
    const top = (window.innerHeight - rect.bottom >= dropHeight)
        ? rect.bottom + 6
        : rect.top - dropHeight - 6;
    dropdown.style.cssText = `position:fixed;z-index:99999;top:${top}px;left:${Math.min(rect.left, window.innerWidth - 200)}px;background:var(--bg-white);border:1px solid var(--border-color);border-radius:10px;box-shadow:0 8px 24px rgba(0,0,0,0.3);overflow:hidden;min-width:180px;`;
    dropdown.innerHTML = STATUSES.map(s =>
        `<button data-val="${s.value}" style="display:block;width:100%;padding:10px 14px;border:none;background:none;text-align:left;cursor:pointer;font-size:13px;font-weight:600;color:var(--text-dark);transition:background 0.1s;"
            onmouseenter="this.style.background='var(--bg-gray)'" onmouseleave="this.style.background='none'">${s.label}</button>`
    ).join('');
    document.body.appendChild(dropdown);

    const close = (e) => {
        if (!dropdown.contains(e.target) && e.target !== btn) {
            dropdown.remove();
            document.removeEventListener('click', close, true);
        }
    };
    setTimeout(() => document.addEventListener('click', close, true), 0);

    dropdown.querySelectorAll('button[data-val]').forEach(statusBtn => {
        statusBtn.addEventListener('click', async () => {
            dropdown.remove();
            document.removeEventListener('click', close, true);
            btn.disabled = true;
            btn.textContent = '...';
            try {
                await addDoc(collection(db, 'anime_lists'), {
                    uid: auth.currentUser.uid,
                    mal_id,
                    title,
                    image,
                    status: statusBtn.dataset.val,
                    score: null,
                    addedAt: new Date(),
                });
                btn.textContent = 'In List';
                btn.classList.add('in-list');
                _advMyListCache?.add(String(mal_id));
                document.querySelectorAll(`.search-quick-add[data-mal="${mal_id}"]`).forEach(b => {
                    b.textContent = 'In List';
                    b.classList.add('in-list');
                });
            } catch(e) {
                btn.textContent = '+ Add';
                btn.disabled = false;
                console.error(e);
            }
        });
    });
};

// --- SEASONAL ARCHIVE ---
let _archiveData = null;

window.openSeasonalArchive = function() {
    document.getElementById('adv-search-main-view').style.display = 'none';
    document.getElementById('adv-archive-view').style.display = 'flex';
    document.getElementById('adv-archive-grid').style.display = 'block';
    document.getElementById('adv-season-results').style.display = 'none';

    const gridEl = document.getElementById('adv-archive-grid');
    if (_archiveData) return; // already rendered

    // Generate grid from current date — no API needed
    const now = new Date();
    const currentYear = now.getFullYear();
    const currentMonth = now.getMonth() + 1;
    const seasonOrder = ['winter', 'spring', 'summer', 'fall'];
    const seasonLabels = { winter: 'Winter', spring: 'Spring', summer: 'Summer', fall: 'Fall' };
    // Season starts: winter=Jan(1), spring=Apr(4), summer=Jul(7), fall=Oct(10)
    const seasonStartMonth = { winter: 1, spring: 4, summer: 7, fall: 10 };

    let html = `<table class="adv-archive-table">
        <thead><tr>
            <th>Year</th><th>Winter</th><th>Spring</th><th>Summer</th><th>Fall</th>
        </tr></thead><tbody>`;

    for (let year = currentYear; year >= 2000; year--) {
        html += `<tr><td>${year}</td>`;
        seasonOrder.forEach(s => {
            const started = year < currentYear || seasonStartMonth[s] <= currentMonth;
            html += started
                ? `<td><button class="adv-season-btn" onclick="loadSeasonAnime(${year},'${s}')">${seasonLabels[s]}</button></td>`
                : `<td style="color:var(--text-muted);text-align:center;font-size:12px;">—</td>`;
        });
        html += '</tr>';
    }
    html += '</tbody></table>';
    gridEl.innerHTML = html;
    _archiveData = true;
};

window.closeSeasonalArchive = function() {
    document.getElementById('adv-archive-view').style.display = 'none';
    document.getElementById('adv-search-main-view').style.display = 'flex';
};

window.backToArchiveGrid = function() {
    document.getElementById('adv-season-results').style.display = 'none';
    document.getElementById('adv-archive-grid').style.display = 'block';
};

window.loadSeasonAnime = async function(year, season) {
    document.getElementById('adv-archive-grid').style.display = 'none';
    const seasonResultsEl = document.getElementById('adv-season-results');
    const gridEl = document.getElementById('adv-season-results-grid');
    const titleEl = document.getElementById('adv-season-title');
    seasonResultsEl.style.display = 'block';

    const label = season.charAt(0).toUpperCase() + season.slice(1);
    titleEl.textContent = `${label} ${year}`;
    gridEl.innerHTML = '<div class="loading" style="padding:40px;grid-column:1/-1;">Loading season...</div>';

    const cacheKey = `season_al_${year}_${season}`;
    const CACHE_TTL = 12 * 60 * 60 * 1000;

    try {
        // Check Firestore cache first
        let items = null;
        try {
            const cSnap = await getDoc(doc(db, 'anime_cache', cacheKey));
            if (cSnap.exists()) {
                const cached = cSnap.data();
                if (Date.now() - (cached.fetchedAt?.toMillis?.() || 0) < CACHE_TTL) items = cached.payload;
            }
        } catch(_) {}

        if (!items) {
            const gql = `query($season:MediaSeason,$year:Int,$page:Int){Page(page:$page,perPage:50){media(season:$season,seasonYear:$year,type:ANIME,sort:[POPULARITY_DESC],isAdult:false){id idMal title{romaji english}coverImage{large}averageScore episodes format}}}`;
            const res = await fetch('https://graphql.anilist.co', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ query: gql, variables: { season: season.toUpperCase(), year, page: 1 } }),
            });
            const json = await res.json();
            items = json.data?.Page?.media || [];
            setDoc(doc(db, 'anime_cache', cacheKey), { payload: items, fetchedAt: new Date() }).catch(() => {});
        }

        if (!items.length) {
            gridEl.innerHTML = '<div style="text-align:center;color:var(--text-muted);padding:40px;grid-column:1/-1;">No anime found for this season.</div>';
            return;
        }

        const myList = await _advGetMyList();
        gridEl.innerHTML = '';
        items.forEach(anime => {
            const title = anime.title?.english || anime.title?.romaji || 'Unknown';
            const image = anime.coverImage?.large || '';
            const malId = anime.idMal;
            const score = anime.averageScore ? `⭐ ${(anime.averageScore / 10).toFixed(1)}` : '';
            const epInfo = anime.format === 'MOVIE' ? 'Movie' : (anime.episodes ? `${anime.episodes} eps` : anime.format || '');
            const inList = malId && myList.has(String(malId));
            const card = document.createElement('div');
            card.className = 'adv-anime-card';
            card.innerHTML = `
                <div class="adv-anime-card-img">
                    <img src="${image}" alt="${title}" loading="lazy" onerror="this.parentElement.style.background='var(--bg-gray-darker)';">
                </div>
                <div class="adv-anime-card-body">
                    <div class="adv-anime-card-title">${title}</div>
                    <div class="adv-anime-card-meta">${epInfo}</div>
                    ${score ? `<div class="adv-anime-card-score">${score}</div>` : ''}
                    ${malId ? `<button class="adv-quick-add-btn search-quick-add ${inList ? 'in-list' : ''}"
                        data-mal="${malId}"
                        data-img="${image}"
                        onclick="event.stopPropagation(); advQuickAdd(this, ${malId}, '${title.replace(/'/g,"\\'")}')">
                        ${inList ? 'In List' : '+ Add'}
                    </button>` : ''}
                </div>`;
            if (malId) {
                card.querySelector('.adv-anime-card-img').addEventListener('click', () => { closeAdvancedSearch(); loadAnimeDetails(malId); });
                card.querySelector('.adv-anime-card-title').addEventListener('click', () => { closeAdvancedSearch(); loadAnimeDetails(malId); });
            }
            gridEl.appendChild(card);
        });

    } catch(e) {
        gridEl.innerHTML = '<div style="text-align:center;color:var(--text-muted);padding:40px;grid-column:1/-1;">Could not load season. Try again later.</div>';
        console.error('loadSeasonAnime error:', e);
    }
};
// ─── Character Database ───────────────────────────────────────────────────────
// WB_CHARACTERS is loaded from characters.js (global, 800+ entries from top 50 anime)
// Search order: local bundle → Firestore cache → AniList API → auto-cache result

const ANILIST_URL = 'https://graphql.anilist.co';

async function _anilistGql(query, variables = {}) {
    const res = await fetch(ANILIST_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
        body: JSON.stringify({ query, variables })
    });
    const json = await res.json();
    if (json.errors) throw new Error(json.errors[0].message);
    return json.data;
}

const _isMetaChar = name => /^(narrator|singer|announcer|voice actor)$/i.test(name.trim());

// Search WB_CHARACTERS bundle by name (fuzzy prefix match)
function _searchLocalChars(q) {
    if (!window.WB_CHARACTERS || !q) return [];
    const lower = q.toLowerCase();
    return window.WB_CHARACTERS.filter(c =>
        !_isMetaChar(c.name) && c.name.toLowerCase().includes(lower)
    ).slice(0, 20);
}

// Search Firestore character cache
async function _searchCachedChars(q) {
    if (!q) return [];
    const lower = q.toLowerCase();
    try {
        const snap = await getDocs(query(
            collection(db, 'characters'),
            where('nameLower', '>=', lower),
            where('nameLower', '<=', lower + ''),
            limit(10)
        ));
        return snap.docs.map(d => ({ id: d.id, ...d.data() }));
    } catch (e) {
        return [];
    }
}

// Search AniList for characters and cache any new results
async function _searchAnilistChars(q) {
    if (!q) return [];
    try {
        const data = await _anilistGql(`
            query ($search: String) {
                Page(perPage: 10) {
                    characters(search: $search, sort: FAVOURITES_DESC) {
                        name { full }
                        image { large }
                        media(perPage: 1, sort: POPULARITY_DESC, type: ANIME) {
                            nodes { title { english romaji } }
                        }
                    }
                }
            }
        `, { search: q });

        const results = (data?.Page?.characters || [])
            .filter(c => c.name?.full && c.image?.large && !_isMetaChar(c.name.full))
            .map(c => ({
                name: c.name.full,
                image: c.image.large,
                anime: c.media?.nodes?.[0]?.title?.english || c.media?.nodes?.[0]?.title?.romaji || ''
            }));

        // Auto-cache results not already in local bundle
        const localNames = new Set((window.WB_CHARACTERS || []).map(c => c.name.toLowerCase()));
        for (const r of results) {
            if (!localNames.has(r.name.toLowerCase())) {
                _cacheCharacter(r).catch(() => {});
            }
        }

        return results;
    } catch (e) {
        console.warn('AniList character search failed:', e.message);
        return [];
    }
}

// Save a character to Firestore cache (fire-and-forget)
async function _cacheCharacter(char) {
    try {
        const nameLower = char.name.toLowerCase();
        const snap = await getDocs(query(
            collection(db, 'characters'),
            where('nameLower', '==', nameLower),
            limit(1)
        ));
        if (snap.empty) {
            await addDoc(collection(db, 'characters'), {
                name: char.name,
                nameLower,
                image: char.image,
                anime: char.anime,
                cachedAt: serverTimestamp()
            });
        }
    } catch (e) { /* non-critical */ }
}

// Main character search — used by bracket/tier list character pickers
// Returns { name, image, anime } objects
window.searchCharacters = async function(q) {
    if (!q || q.length < 2) return [];

    // 1. Local bundle (instant)
    const local = _searchLocalChars(q);
    if (local.length >= 8) return local;

    // 2. Firestore cache + AniList in parallel for gaps
    const [cached, remote] = await Promise.all([
        _searchCachedChars(q),
        _searchAnilistChars(q)
    ]);

    // Merge: local first, then remote, dedup by name
    const seen = new Set(local.map(c => c.name.toLowerCase()));
    const merged = [...local];
    for (const c of [...cached, ...remote]) {
        if (!seen.has(c.name.toLowerCase())) {
            seen.add(c.name.toLowerCase());
            merged.push(c);
        }
    }
    return merged.slice(0, 20);
};

